import{_ as a,a as s,c as i,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"程序员英语 08：一次完整的阅读与协作实战","description":"用原创导入工具案例完成文档阅读、报错复述、Issue、PR、评审和口头说明，并附参考答案。","frontmatter":{"title":"程序员英语 08：一次完整的阅读与协作实战","description":"用原创导入工具案例完成文档阅读、报错复述、Issue、PR、评审和口头说明，并附参考答案。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"程序员英语","summary":"用原创导入工具案例完成文档阅读、报错复述、Issue、PR、评审和口头说明，并附参考答案。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"程序员英语 07：会议、听力与技术表达","link":"/life/english/programmer/listening-speaking"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"程序员英语 07：会议、听力与技术表达","link":"/life/english/programmer/listening-speaking"},"next":false},"headers":[],"relativePath":"life/english/programmer/practice.md","filePath":"life/english/programmer/practice.md"}'),l={name:"life/english/programmer/practice.md"};function t(o,e,r,p,c,d){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="程序员英语-08-一次完整的阅读与协作实战" tabindex="-1">程序员英语 08：一次完整的阅读与协作实战 <a class="header-anchor" href="#程序员英语-08-一次完整的阅读与协作实战" aria-label="Permalink to &quot;程序员英语 08：一次完整的阅读与协作实战&quot;">​</a></h1><p>这一课把前面的技能放进同一个任务。先独立完成，再打开解析；参考答案不是唯一表达，但不能改变给定事实。</p><h2 id="材料与任务" tabindex="-1">材料与任务 <a class="header-anchor" href="#材料与任务" aria-label="Permalink to &quot;材料与任务&quot;">​</a></h2><p>虚构工具 <code>row-loader 1.3</code> 的说明：</p><blockquote><p>The loader skips blank lines. A line containing only spaces is not considered blank. In strict mode, an invalid record stops loading. In default mode, invalid records are reported and loading continues. Existing output files are preserved unless replacement is explicitly enabled.</p></blockquote><p>测试条件：Linux；默认模式；输出文件原先不存在。输入如下，第 3 行是空行：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name,score</span></span>
<span class="line"><span>Lin,8</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Mo,9</span></span></code></pre></div><p>观察：工具在第 3 行停止，显示 <code>invalid record</code>；删除第 3 行后可以读完。尚未测试只含空格的行、严格模式和已有输出文件。以上结果均是题目设定。</p><p>完成六件事：</p><ol><li>用中文列出三个确定行为和两个尚待检查项。</li><li>用一句英文复述失败，并区分现象与原因假设。</li><li>写一个 Issue 标题和复现步骤。</li><li>假设你已修正空行分支，且新增空行测试通过，写 PR 摘要与验证边界。</li><li>对“直接对每行 <code>trim()</code> 后跳过空字符串”的建议写评审意见。</li><li>做一分钟状态说明，最后提出一个具体请求。</li></ol><h2 id="参考答案-阅读与复述" tabindex="-1">参考答案：阅读与复述 <a class="header-anchor" href="#参考答案-阅读与复述" aria-label="Permalink to &quot;参考答案：阅读与复述&quot;">​</a></h2><details class="details custom-block"><summary>查看任务 1～2 的答案</summary><p>确定行为：应跳过空行；仅空格的行不属于空行；默认模式下无效记录应报告后继续。另一个已知约束是未明确启用替换时保留已有输出。</p><p>待检查项可选：严格模式是否符合说明、已有输出是否被保留、只含空格的行是否走无效记录路径。这些都有预期规则，但目前没有测试结果。</p><p>失败复述：<code>In default mode, row-loader 1.3 stops at a blank line instead of skipping it.</code></p><p>原因假设：<code>The blank line may be reaching record validation before it is skipped.</code> 加上 <code>may</code>，因为目前只有输入与输出证据，没有执行路径证据。</p></details><h2 id="参考答案-issue-与-pr" tabindex="-1">参考答案：Issue 与 PR <a class="header-anchor" href="#参考答案-issue-与-pr" aria-label="Permalink to &quot;参考答案：Issue 与 PR&quot;">​</a></h2><details class="details custom-block"><summary>查看任务 3～4 的答案</summary><p>Issue 标题：<code>Default loading stops at a blank line in row-loader 1.3</code>。</p><p>步骤：<code>1. Save the sample as a UTF-8 file. 2. Run row-loader 1.3 in default mode with a new output path. 3. Observe the error at line 3.</code> 实际提交应附完整样例和真实调用命令；题目没有给命令格式，因此不能编造一个看似可运行的命令。</p><p>PR 摘要与验证：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>This change skips blank lines before validating records.</span></span>
<span class="line"><span>The regression case with a blank line between two records now passes.</span></span>
<span class="line"><span>Whitespace-only lines, strict mode, and existing output files have not been tested yet.</span></span></code></pre></div><p>题目只确认一个新增测试通过，不能扩写为“所有测试通过”或“所有导入错误都已修复”。</p></details><h2 id="参考答案-评审与表达" tabindex="-1">参考答案：评审与表达 <a class="header-anchor" href="#参考答案-评审与表达" aria-label="Permalink to &quot;参考答案：评审与表达&quot;">​</a></h2><details class="details custom-block"><summary>查看任务 5～6 的答案</summary><p>评审：<code>Trimming each line would also classify whitespace-only lines as blank, which conflicts with the documented rule. Could we detect empty lines without changing the record contents?</code></p><p>状态说明：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I reproduced a default-mode failure at a blank line in row-loader 1.3.</span></span>
<span class="line"><span>The blank-line change is in place, and its regression case passes.</span></span>
<span class="line"><span>I still need to check strict mode, whitespace-only lines, and existing output files.</span></span>
<span class="line"><span>Could someone review the blank-line condition before I finish those checks?</span></span></code></pre></div><p>它交代已做什么、证据覆盖哪里、缺少什么、希望别人做什么。录音和现场反馈仍需自行完成，文字答案不能代替听说验证。</p></details><h2 id="复习时只盯一个问题" tabindex="-1">复习时只盯一个问题 <a class="header-anchor" href="#复习时只盯一个问题" aria-label="Permalink to &quot;复习时只盯一个问题&quot;">​</a></h2><p>如果总漏掉 <code>unless</code>，下一次专门找含例外条件的句子；如果总写 <code>It doesn&#39;t work</code>，每次强制补齐对象与触发条件；如果容易把计划写成结果，就核对 <code>will check</code> 与 <code>checked</code>。</p><p>用一周后重做同题检查是否真正掌握，再换一个真实的公开项目练习。公开提交前先在本地完成草稿，遵守项目模板，删除敏感信息。复习可回到<a href="/life/english/programmer/overview">学习路线</a>，精读参考 <a href="https://developers.google.com/tech-writing/one" target="_blank" rel="noopener noreferrer">Google Technical Writing One</a>。</p>`,19)])])}const g=a(l,[["render",t]]);export{u as __pageData,g as default};
